+function drawBlob(b, tNow) {
+  const hop = reducedMotion ? 0 : Math.abs(Math.sin(tNow * 6 + b.phase)) * (Math.hypot(b.vx, b.vy) > 5 ? 5 : 1.6);
+  const p = project(b.x, b.y, hop);
